// ---------- EDIT THESE VALUES ----------
const CONFIG = {
  businessName: 'SnowbeltTech',
  ownerPhone: 'REDACTED_OWNER_PHONE',
  twilioFromPhone: 'REDACTED_TWILIO_PHONE',
  googleSheetId: 'REDACTED_SHEET_ID',
  sheetTabName: 'Inquiries',
  timezone: 'America/New_York',
  smsConsentVersion: '2026-08-v1',
  smsConsentText: 'By checking this box, I agree to receive text messages from SnowbeltTech regarding this request. Message frequency varies, typically 1-3 messages per inquiry. Message and data rates may apply. Reply STOP to opt out or HELP for help. Terms: https://snowbelttech.com/terms. Privacy: https://snowbelttech.com/privacy.'
};
// ---------------------------------------

const input = $json.body ?? $json;

const pick = (...keys) => {
  for (const key of keys) {
    const value = input[key];
    if (value !== undefined && value !== null && String(value).trim() !== '') return value;
  }
  return '';
};

const oneLine = (value) => String(value ?? '').replace(/\s+/g, ' ').trim();
const multiLine = (value) => String(value ?? '').replace(/\r\n/g, '\n').trim().slice(0, 5000);

const isChecked = (value) => {
  if (Array.isArray(value)) return value.length > 0;
  return ['true', 'yes', 'on', '1', 'checked'].includes(oneLine(value).toLowerCase());
};

const normalizeUsPhone = (value) => {
  const digits = String(value ?? '').replace(/\D/g, '');
  if (digits.length === 10) return '+1' + digits;
  if (digits.length === 11 && digits.startsWith('1')) return '+' + digits;
  return '';
};

const safeSms = (value, maxLength = 155) => {
  let text = oneLine(value)
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u2013\u2014]/g, '-')
    .replace(/\u2026/g, '...')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\x20-\x7E]/g, ' ');
  text = oneLine(text);
  return text.length > maxLength ? text.slice(0, maxLength - 3) + '...' : text;
};

const name = oneLine(pick('name', 'Name'));
const businessName = oneLine(pick('businessName', 'business_name', 'Business Name'));
const email = oneLine(pick('email', 'Email')).toLowerCase();
const phoneRaw = oneLine(pick('phone', 'Phone'));
const phoneE164 = normalizeUsPhone(phoneRaw);
const businessType = oneLine(pick('businessType', 'business_type', 'Business Type'));
const toTextList = (value) => {
  if (Array.isArray(value)) return value.flatMap(toTextList);
  if (value && typeof value === 'object') return Object.values(value).flatMap(toTextList);
  const text = oneLine(value);
  return text ? [text] : [];
};

const helpRaw = pick('helpRequested', 'help_requested', 'Help Requested', 'needs');
const helpRequested = toTextList(helpRaw).join(', ');
const improvementRaw = pick('improvementDetails', 'improvement_details', 'Improvement Details', 'goal');
const improvementDetails = multiLine(improvementRaw).replace(/^Tell us what you would like to improve:\s*/i, '');
const preferredContact = oneLine(pick('preferredContact', 'preferred_contact', 'Preferred Contact'));
const emailMarketingConsent = isChecked(pick('emailMarketingConsent', 'email_marketing_consent', 'Email Marketing Consent'));
const smsConsent = isChecked(pick('smsConsent', 'sms_consent', 'SMS Consent'));
const validCustomerPhone = /^\+1\d{10}$/.test(phoneE164);
const canSendCustomerSms = validCustomerPhone && smsConsent;
const inquiryId = 'INQ-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-' + Math.random().toString(36).slice(2, 7).toUpperCase();

let submittedAt = new Date().toISOString();
try {
  submittedAt = new Date().toLocaleString('en-US', { timeZone: CONFIG.timezone, hour12: false });
} catch (error) {}

const contact = phoneE164 || email || phoneRaw || 'no contact provided';
const ownerSmsMessage = safeSms(CONFIG.businessName + ': New inquiry ' + inquiryId + ' from ' + (name || 'unnamed') + ', ' + contact + '. Help: ' + (helpRequested || 'not specified') + '. See Google Sheet.');
const customerSmsMessage = safeSms(CONFIG.businessName + ': Thanks for contacting us. We received your request and will follow up shortly. Replies are not monitored. Reply STOP to opt out.');

return [{
  json: {
    ...CONFIG,
    phoneE164,
    phoneRaw,
    validCustomerPhone,
    canSendCustomerSms,
    ownerSmsMessage,
    customerSmsMessage,
    inquiryId,
    'Inquiry ID': inquiryId,
    'Submitted At': submittedAt,
    'Source': 'Web',
    'Name': name,
    'Business Name': businessName,
    'Email': email,
    'Phone': phoneE164,
    'Phone (Raw)': phoneRaw,
    'Business Type': businessType,
    'Help Requested': helpRequested,
    'Improvement Details': improvementDetails,
    'Preferred Contact': preferredContact,
    'Email Marketing Consent': emailMarketingConsent ? 'Yes' : 'No',
    'SMS Consent': smsConsent ? 'Yes' : 'No',
    'SMS Consent Text': smsConsent ? CONFIG.smsConsentText : '',
    'SMS Consent Version': smsConsent ? CONFIG.smsConsentVersion : '',
    'Customer SMS Status': 'Pending',
    'Customer Message SID': '',
    'Owner SMS Status': 'Pending',
    'Owner Message SID': '',
    'Processing Error': ''
  }
}];

const base = $('Normalize Vapi Call').isExecuted
  ? $('Normalize Vapi Call').first().json
  : $('Normalize and Configure').first().json;

const result = $input.first().json;

const errorText = result.error
  ? (
      typeof result.error === 'string'
        ? result.error
        : (
            result.error.message ||
            result.error.description ||
            JSON.stringify(result.error)
          )
    )
  : '';

return [
  {
    json: {
      ...base,

      ownerSmsStatus: errorText
        ? (
            'Failed: ' +
            errorText
          ).slice(0, 250)
        : (
            'Accepted by Twilio (' +
            (result.status || 'queued') +
            ')'
          ),

      ownerMessageSid:
        result.sid || '',

      processingError: errorText
        ? (
            'Owner SMS: ' +
            errorText
          ).slice(0, 500)
        : '',
    },
  },
];

const context = $('Capture Owner SMS').first().json;
const result = $input.first().json;
const errorText = result.error
  ? (typeof result.error === 'string' ? result.error : (result.error.message || result.error.description || JSON.stringify(result.error)))
  : '';
const combinedError = [context.processingError, errorText ? 'Customer SMS: ' + errorText : ''].filter(Boolean).join(' | ').slice(0, 500);

return [{ json: {
  'Inquiry ID': context.inquiryId,
  'Customer SMS Status': errorText ? ('Failed: ' + errorText).slice(0, 250) : 'Accepted by Twilio (' + (result.status || 'queued') + ')',
  'Customer Message SID': result.sid || '',
  'Owner SMS Status': context.ownerSmsStatus,
  'Owner Message SID': context.ownerMessageSid,
  'Processing Error': combinedError
} }];

const context = $input.first().json;
let status = 'Skipped - no SMS consent';
if (!context.validCustomerPhone) {
  status = context.phoneRaw ? 'Skipped - invalid US phone number' : 'Skipped - no phone number';
}

return [{ json: {
  'Inquiry ID': context.inquiryId,
  'Customer SMS Status': status,
  'Customer Message SID': '',
  'Owner SMS Status': context.ownerSmsStatus,
  'Owner Message SID': context.ownerMessageSid,
  'Processing Error': context.processingError || ''
} }];

const input = $input.first().json;
const body = input.body ?? input;
const message = body.message ?? body;

const CONFIG = {
  // Copy the owner SMS destination from the website normalization node.
  ownerPhone: 'REDACTED_OWNER_PHONE',

  twilioFromPhone: 'REDACTED_TWILIO_PHONE',
  googleSheetId: 'REDACTED_SHEET_ID',
  sheetTabName: 'Inquiries',
  timezone: 'America/New_York',
  smsConsentVersion: '2026-08-v1',
  smsConsentText:
    'By checking this box, I agree to receive text messages from SnowbeltTech regarding this request. Message frequency varies, typically 1-3 messages per inquiry. Message and data rates may apply. Reply STOP to opt out or HELP for help. Terms: https://snowbelttech.com/terms. Privacy: https://snowbelttech.com/privacy.',
};

if (!/^\+\d{10,15}$/.test(CONFIG.ownerPhone)) {
  throw new Error(
    'Replace ownerPhone with the owner SMS destination in E.164 format.'
  );
}

if (message.type !== 'end-of-call-report') {
  return [];
}

function findLeadOutput(node) {
  if (!node || typeof node !== 'object') return null;

  const validNames = [
    'SnowBelt Voice Lead',
    'SnowBelt Voice Lead Data',
  ];

  if (
    validNames.includes(node.name) &&
    node.result &&
    typeof node.result === 'object'
  ) {
    return node;
  }

  for (const value of Object.values(node)) {
    const found = findLeadOutput(value);

    if (found) {
      return found;
    }
  }

  return null;
}

function findCustomerNumber(node) {
  if (!node || typeof node !== 'object') return null;

  if (
    node.customer &&
    typeof node.customer === 'object' &&
    node.customer.number
  ) {
    return node.customer.number;
  }

  for (const value of Object.values(node)) {
    const found = findCustomerNumber(value);

    if (found) {
      return found;
    }
  }

  return null;
}

function normalizeUSPhone(value) {
  if (!value) return null;

  const original = String(value).trim();

  if (/^\+\d{10,15}$/.test(original)) {
    return original;
  }

  const digits = original.replace(/\D/g, '');

  if (digits.length === 10) {
    return `+1${digits}`;
  }

  if (digits.length === 11 && digits.startsWith('1')) {
    return `+${digits}`;
  }

  return null;
}

function getRawUSPhone(value) {
  if (!value) return '';

  const digits = String(value).replace(/\D/g, '');

  if (digits.length === 11 && digits.startsWith('1')) {
    return digits.slice(1);
  }

  return digits;
}

const outputContainer = findLeadOutput(message);

if (!outputContainer) {
  throw new Error(
    'SnowBelt Voice Lead result was not found in the Vapi end-of-call payload.'
  );
}

const lead = outputContainer.result;
const callerNumber = normalizeUSPhone(
  findCustomerNumber(message)
);

let callbackNumber = null;

if (lead.useCallingNumber === true) {
  callbackNumber = callerNumber;
} else if (lead.alternateCallbackNumber) {
  callbackNumber = normalizeUSPhone(
    lead.alternateCallbackNumber
  );
}

if (lead.useCallingNumber === true && !callbackNumber) {
  throw new Error(
    'The caller selected the calling number, but Vapi customer.number was not found.'
  );
}

const callId =
  message.call?.id ??
  input.headers?.['x-call-id'] ??
  null;

const rawTimestamp = message.timestamp ?? Date.now();

const timestampMilliseconds =
  rawTimestamp < 1000000000000
    ? rawTimestamp * 1000
    : rawTimestamp;

const receivedDate = new Date(timestampMilliseconds);

if (Number.isNaN(receivedDate.getTime())) {
  throw new Error('The Vapi timestamp is invalid.');
}

const submittedAt = receivedDate.toLocaleString(
  'en-US',
  {
    timeZone: CONFIG.timezone,
    hour12: false,
  }
);

const datePart = new Intl.DateTimeFormat('en-CA', {
  timeZone: CONFIG.timezone,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
})
  .format(receivedDate)
  .replace(/-/g, '');

const idSuffix = String(callId ?? timestampMilliseconds)
  .replace(/[^a-zA-Z0-9]/g, '')
  .slice(-6)
  .toUpperCase();

const inquiryId = `INQ-${datePart}-V${idSuffix}`;

const phoneRaw = getRawUSPhone(callbackNumber);

const validCustomerPhone =
  typeof callbackNumber === 'string' &&
  /^\+\d{10,15}$/.test(callbackNumber);

// Voice-call SMS consent has not been implemented yet.
const smsConsent = false;
const canSendCustomerSms =
  validCustomerPhone && smsConsent;

const displayName =
  lead.fullName || 'Unknown caller';

const requestedHelp =
  lead.serviceRequested || 'not specified';

let ownerContact = 'no callback number';

if (callbackNumber) {
  ownerContact = callbackNumber;
} else if (callerNumber) {
  ownerContact =
    `${callerNumber} ` +
    '(caller ID; callback not confirmed)';
}

const ownerSmsMessage =
  `SnowbeltTech: New voice inquiry ${inquiryId} ` +
  `from ${displayName}, ${ownerContact}. ` +
  `Help: ${requestedHelp}. See Google Sheet.`;

const customerSmsMessage =
  'SnowbeltTech: Thanks for contacting us. ' +
  'We received your request and will follow up shortly. ' +
  'Replies are not monitored. Reply STOP to opt out.';

const endedReason =
  message.endedReason ??
  message.call?.endedReason ??
  null;

return [
  {
    json: {
      // Shared normalized configuration and values.
      source: 'voice_call',
      leadId: callId,
      callId,
      receivedAt: receivedDate.toISOString(),

      ownerPhone: CONFIG.ownerPhone,
      twilioFromPhone: CONFIG.twilioFromPhone,
      googleSheetId: CONFIG.googleSheetId,
      sheetTabName: CONFIG.sheetTabName,
      timezone: CONFIG.timezone,
      smsConsentVersion: CONFIG.smsConsentVersion,
      smsConsentText: CONFIG.smsConsentText,

      phoneE164: callbackNumber,
      phoneRaw,
      callerPhone: callerNumber,
      validCustomerPhone,
      canSendCustomerSms,

      ownerSmsMessage,
      customerSmsMessage,
      inquiryId,

      // Original normalized voice fields.
      fullName: lead.fullName ?? null,
      phone: callbackNumber,
      email: lead.email ?? null,
      businessName: lead.businessName ?? null,
      businessType: lead.businessType ?? null,
      serviceRequested:
        lead.serviceRequested ?? null,
      inquiryDetails:
        lead.inquiryDetails ?? null,
      details:
        lead.inquiryDetails ?? null,

      preferredCallbackDate:
        lead.preferredCallbackDate ?? null,
      preferredCallbackTime:
        lead.preferredCallbackTime ?? null,
      callbackDateConfirmed:
        lead.callbackDateConfirmed ?? false,

      useCallingNumber:
        lead.useCallingNumber ?? false,
      alternateCallbackNumber:
        lead.alternateCallbackNumber ?? null,

      isLead: lead.isLead ?? false,
      callClassification:
        lead.callClassification ?? 'uncertain',
      callSummary:
        lead.callSummary ?? null,
      reviewRecommended:
        lead.reviewRecommended ?? false,
      reviewReason:
        lead.reviewReason ?? null,

      smsConsent,
      smsConsentSource: 'not_collected',
      endedReason,
      structuredOutputName:
        outputContainer.name,

      // Existing Google Sheet column names.
      'Inquiry ID': inquiryId,
      'Submitted At': submittedAt,
      'Name': lead.fullName ?? '',
      'Business Name':
        lead.businessName ?? '',
      'Email': lead.email ?? '',
      'Phone': callbackNumber ?? '',
      'Phone (Raw)': phoneRaw,
      'Business Type':
        lead.businessType ?? '',
      'Help Requested':
        lead.serviceRequested ?? '',
      'Improvement Details':
        lead.inquiryDetails ??
        lead.callSummary ??
        '',
      'Preferred Contact': 'Phone',
      'Email Marketing Consent': 'No',
      'SMS Consent':
        smsConsent ? 'Yes' : 'No',
      'SMS Consent Text':
        smsConsent
          ? CONFIG.smsConsentText
          : '',
      'SMS Consent Version':
        smsConsent
          ? CONFIG.smsConsentVersion
          : '',
      'Customer SMS Status': 'Pending',
      'Customer Message SID': '',
      'Owner SMS Status': 'Pending',
      'Owner Message SID': '',
      'Processing Error': '',

      // Voice-specific fields for additional Sheet columns.
      'Source': 'Voice Call',
      'Caller ID': callerNumber ?? '',
      'Call ID': callId ?? '',
      'Call Classification':
        lead.callClassification ?? 'uncertain',
      'Call Summary':
        lead.callSummary ?? '',
      'Preferred Callback Date':
        lead.preferredCallbackDate ?? '',
      'Preferred Callback Time':
        lead.preferredCallbackTime ?? '',
      'Review Recommended':
        lead.reviewRecommended
          ? 'Yes'
          : 'No',
      'Review Reason':
        lead.reviewReason ?? '',
    },
  },
];
